/**
 * Bibliography database — CSL-JSON as authoritative source.
 *
 * This file replaces `references.bib` as the source of truth.
 * BibTeX is now a downstream render target, generated by
 * `pipeline/export-bibtex.ts`.
 *
 * ## Key convention
 *
 * Each entry's `id` follows the BibTeX key convention:
 *   <firstauthorlastname><year>  (all lower-case)
 *   e.g. chenier2026, einstein1905
 *
 * ## Adding entries
 *
 * Use the `ref()` builder which validates via Zod at construction time.
 * Fields follow the CSL-JSON spec: https://citeproc-js.readthedocs.io/en/latest/csl-json/markup.html
 *
 * ## Downstream consumers
 *
 * - `pipeline/export-bibtex.ts` → `references.bib` (for LaTeX)
 * - `pipeline/validate-references.ts` → cross-checks against Lean `-- Ref:` comments
 * - `pipeline/export-json.ts` → `references.json` (for viewer/MCP)
 * - Content blocks may reference entries by `id` in `uses[]` or `meta.cites[]`
 *
 * @module content/schema/references
 */

import { z } from "zod";
import type { Data as CSLData, Person as CSLPerson, Date as CSLDate, ItemType } from "csl-json";

// ── Re-exports for consumer convenience ─────────────────────────
export type { CSLData, CSLPerson, CSLDate, ItemType };

// ── Zod schema for CSL-JSON validation ──────────────────────────

const CSLPersonSchema = z.object({
  family: z.string().optional(),
  given: z.string().optional(),
  suffix: z.string().optional(),
  "non-dropping-particle": z.string().optional(),
  "dropping-particle": z.string().optional(),
  literal: z.string().optional(),
}).refine(
  (p) => p.family || p.literal,
  { message: "Person must have either `family` or `literal` name" },
);

const CSLDateSchema = z.object({
  "date-parts": z.array(
    z.tuple([z.union([z.string(), z.number()])]).rest(z.union([z.string(), z.number()]).optional()),
  ).optional(),
  raw: z.string().optional(),
  literal: z.string().optional(),
  season: z.union([z.number(), z.string()]).optional(),
  circa: z.boolean().optional(),
}).refine(
  (d) => d["date-parts"] || d.raw || d.literal,
  { message: "Date must have `date-parts`, `raw`, or `literal`" },
);

export const CSLItemTypeSchema = z.enum([
  "article", "article-journal", "article-magazine", "article-newspaper",
  "bill", "book", "broadcast", "chapter", "dataset", "entry",
  "entry-dictionary", "entry-encyclopedia", "figure", "graphic",
  "interview", "legal_case", "legislation", "manuscript", "map",
  "motion_picture", "musical_score", "pamphlet", "paper-conference",
  "patent", "personal_communication", "post", "post-weblog",
  "report", "review", "review-book", "song", "speech", "thesis",
  "treaty", "webpage",
]);

export const CSLEntrySchema = z.object({
  id: z.string().min(1, "Entry must have an id"),
  type: CSLItemTypeSchema,
  title: z.string().min(1, "Entry must have a title"),

  // Person fields
  author: z.array(CSLPersonSchema).optional(),
  editor: z.array(CSLPersonSchema).optional(),
  translator: z.array(CSLPersonSchema).optional(),
  "collection-editor": z.array(CSLPersonSchema).optional(),
  "container-author": z.array(CSLPersonSchema).optional(),

  // Date fields
  issued: CSLDateSchema.optional(),
  accessed: CSLDateSchema.optional(),
  "original-date": CSLDateSchema.optional(),

  // String fields
  "container-title": z.string().optional(),
  "collection-title": z.string().optional(),
  publisher: z.string().optional(),
  "publisher-place": z.string().optional(),
  page: z.string().optional(),
  DOI: z.string().optional(),
  URL: z.string().optional(),
  ISBN: z.string().optional(),
  ISSN: z.string().optional(),
  note: z.string().optional(),
  abstract: z.string().optional(),
  genre: z.string().optional(),
  number: z.union([z.string(), z.number()]).optional(),

  // Number fields
  volume: z.union([z.string(), z.number()]).optional(),
  issue: z.union([z.string(), z.number()]).optional(),
  edition: z.union([z.string(), z.number()]).optional(),
  "chapter-number": z.union([z.string(), z.number()]).optional(),
  "collection-number": z.union([z.string(), z.number()]).optional(),
  "number-of-pages": z.union([z.string(), z.number()]).optional(),
  "number-of-volumes": z.union([z.string(), z.number()]).optional(),
}).passthrough();

// ── Builder ─────────────────────────────────────────────────────

/** Validates a CSL-JSON entry at construction time. */
export function ref(data: CSLData): CSLData {
  CSLEntrySchema.parse(data);
  return data;
}

